import type { Card, AgeBand, LocationId, Source } from "../types";

// Study cards for the Moon outpost game. Every card carries a real source (NASA data / peer-reviewed paper)
// and a question that is answerable from the card body. Cadet = 3 options, Specialist = 4 options.

// ---- Sources (reused) ----
const BVAD: Source = {
  name: "NASA NTRS",
  url: "https://ntrs.nasa.gov/citations/20210024855",
  detail: "Life Support Baseline Values and Assumptions Document (BVAD), Ewert, Chen & Powell, NASA/TP-20210024855",
};
const bvad = (detail: string): Source => ({ ...BVAD, detail: `BVAD (NTRS 20210024855) · ${detail}` });
const TREK: Source = { name: "NASA Moon Trek", url: "https://trek.nasa.gov/moon/", detail: "LRO LOLA / Diviner maps of the Moon" };
const trek = (detail: string): Source => ({ ...TREK, detail });
const OSDR: Source = { name: "NASA OSDR", url: "https://osdr.nasa.gov/bio/", detail: "Open Science Data Repository" };
const CE4: Source = {
  name: "Science Advances (Chang'e-4 LND)",
  url: "https://doi.org/10.1126/sciadv.aaz1334",
  detail: "Zhang et al. 2020, First measurements of the radiation dose on the lunar surface · 1.37 mSv/day",
};
const MSLRAD: Source = {
  name: "MSL RAD (PDS PPI)",
  url: "https://pds-ppi.igpp.ucla.edu/data/MSL-M-RAD-3-RDR-V1.0/",
  detail: "Curiosity RAD data; Hassler et al. 2014, Science 343 · ~0.67 mSv/day on Mars surface",
};
const DSN: Source = { name: "NASA Deep Space Network", url: "https://deepspace.jpl.nasa.gov/", detail: "JPL DSN: Goldstone, Madrid, Canberra" };
const IMG = (id: string, detail: string): Source => ({ name: "NASA Image and Video Library", url: `https://images.nasa.gov/details/${id}`, detail });
const donki = (url: string, detail: string): Source => ({ name: "NASA DONKI", url, detail });

type Q = { q: string; options: string[]; correct: number; hint: string; explain: string };
function card(
  id: string,
  location: LocationId,
  age: AgeBand,
  title: string,
  body: string,
  stat: [string, string],
  source: Source,
  question: Q,
  image?: [string, string],
): Card {
  const c: Card = { id, location, age, title, body, stat: { value: stat[0], label: stat[1] }, source, question };
  if (image) {
    c.image = `/moon/img/${image[0]}.jpg`;
    c.imageCredit = image[1];
  }
  return c;
}

