// Spread the correct answer over all positions: rotate options by a fixed amount per card (deterministic).
// Ordered/numeric options (e.g. "0.9 kg, 1.8 kg, ...", "I, II, III") keep their natural order.
function spread(c: Card): Card {
  const o = c.question.options;
  if (o.some((x) => /^\d|^Artemis /.test(x))) return c;
  let h = 0;
  for (const ch of c.id) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const k = h % o.length;
  if (k === 0) return c;
  const options = o.map((_, i) => o[(i + k) % o.length]);
  const correct = (c.question.correct - k + o.length) % o.length;
  return { ...c, question: { ...c.question, options, correct } };
}

export const CARDS: Card[] = [...HABITAT, ...GREENHOUSE, ...SOLAR, ...SHELTER, ...RADIO, ...LAB].map(spread);
